import { useParams, useNavigate } from "react-router-dom";
import { projectsData } from "../data/projects";
import { useState, useMemo } from "react";
import { ArrowLeft, ExternalLink, Github } from "lucide-react";
import SEO from "../components/SEO";
import ArchitectureDiagram from "../components/ArchitectureDiagram";
import "../styles/ProjectDetail.css";

export default function ProjectDetail() {
  const { id } = useParams();
  const navigate = useNavigate();

  const project = projectsData.find(p => p.id === id);
  const [index, setIndex] = useState(0);

  // Architecture diagram nodes, derived only from data the project already
  // states — never invented. Prefers an explicit arrow-pipeline already
  // written in `solution` (e.g. "crawl → AI audit → GPT synthesis →
  // email delivery"); falls back to the project's own `technologies` list,
  // in the order it's already given, when no such pipeline exists.
  const archNodes = useMemo(() => {
    if (!project) return [];
    if (project.solution?.includes('→')) {
      const match = project.solution.match(/[A-Za-z][A-Za-z0-9 /&-]*(?:\s*→\s*[A-Za-z][A-Za-z0-9 /&-]*)+/);
      if (match) {
        return match[0]
          .split('→')
          .map((s) => s.trim().split(/\s+/).slice(0, 4).join(' ')) // cap trailing modifier phrases
          .filter(Boolean);
      }
    }
    return project.technologies || [];
  }, [project]);

  if (!project) return <h2>Project not found</h2>;

  return (
    <>
    <SEO
      title={`${project.title} | Shagun Tyagi — Project Case Study`}
      desc={project.description}
      path={`/project/${project.id}`}
      image={project.image}
      breadcrumb={[
        { name: "Projects", path: "/projects" },
        { name: project.title, path: `/project/${project.id}` },
      ]}
    />
    <section className="project-detail-page">
      <div className="container">

        {/* BACK */}
        <button className="back-btn" onClick={() => navigate(-1)}>
          <ArrowLeft size={16} /> Back
        </button>

        {/* MAIN GLASS CARD */}
        <div className="project-detail-card">

          {/* TITLE */}
          <h1 className="title">{project.title}</h1>
          <p className="subtitle">{project.description}</p>

          {/* 🔥 GRID LAYOUT */}
          <div className="project-detail-grid">

            {/* LEFT SIDE — MEDIA */}
            <div className="project-media">

              {project.video ? (
                <div className="video-wrapper">
                  <iframe
                    src={project.video}
                    title="Project Demo"
                    allowFullScreen
                  />
                </div>
              ) : (
                <div className="carousel">
                  <img
                    src={project.images?.[index] || project.image}
                    alt={project.title}
                  />

                  {project.images?.length > 1 && (
                    <>
                      <button
                        className="nav prev"
                        onClick={() =>
                          setIndex((index - 1 + project.images.length) % project.images.length)
                        }
                      >
                        ‹
                      </button>

                      <button
                        className="nav next"
                        onClick={() =>
                          setIndex((index + 1) % project.images.length)
                        }
                      >
                        ›
                      </button>
                    </>
                  )}
                </div>
              )}

            </div>

            {/* RIGHT SIDE — PANEL */}
            <div className="project-side">

              {/* TECH STACK */}
              <div className="side-card">
                <h4>Tech Stack</h4>

                <div className="tech-stack">
                  {project.technologies.map((t, i) => (
                    <span key={i} className="tech-pill">{t}</span>
                  ))}
                </div>
              </div>

              {/* LINKS */}
              <div className="side-card">
                <h4>Links</h4>

                {project.githubUrl && (
                  <a
                    href={project.githubUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="side-link"
                  >
                    <Github size={16} /> GitHub Repository
                  </a>
                )}

                {project.liveUrl && (
                  <a
                    href={project.liveUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="side-link"
                  >
                    <ExternalLink size={16} /> Live Demo
                  </a>
                )}
              </div>

            </div>
          </div>

          {/* CASE STUDY: PROBLEM */}
          {project.problem && (
            <div className="detail-section">
              <h3>The Problem</h3>
              <p>{project.problem}</p>
            </div>
          )}

          {/* CASE STUDY: SOLUTION */}
          {project.solution && (
            <div className="detail-section">
              <h3>Solution &amp; Approach</h3>
              <p>{project.solution}</p>
            </div>
          )}

          {/* ARCHITECTURE — derived from the pipeline above or the tech
              stack list below; never invented content. */}
          {archNodes.length >= 2 && (
            <div className="detail-section">
              <h3>Architecture</h3>
              <ArchitectureDiagram nodes={archNodes} />
            </div>
          )}

          {/* OVERVIEW */}
          {project.overview && (
            <div className="detail-section">
              <h3>Overview</h3>
              <p>{project.overview}</p>
            </div>
          )}

          {/* CASE STUDY: RESULTS */}
          {project.results && (
            <div className="detail-section">
              <h3>Results &amp; Impact</h3>
              <ul>
                {project.results.map((r, i) => (
                  <li key={i}>{r}</li>
                ))}
              </ul>
            </div>
          )}

          {/* ACHIEVEMENTS */}
          {project.achievements && (
            <div className="detail-section">
              <h3>Key Achievements</h3>
              <ul>
                {project.achievements.map((a, i) => (
                  <li key={i}>{a}</li>
                ))}
              </ul>
            </div>
          )}

          {/* CASE STUDY: FUTURE WORK */}
          {project.futureWork && (
            <div className="detail-section">
              <h3>Future Improvements</h3>
              <p>{project.futureWork}</p>
            </div>
          )}

        </div>
      </div>
    </section>
    </>
  );
}